namespace TutorFlow.Application.Retrieval;

/// <summary>Unidad indexable del reglamento (SPEC 7.2).</summary>
public sealed record Chunk(
    string ChunkId,
    string Documento,
    string Seccion,
    string Titulo,
    string Texto,
    bool Vigente,
    bool Untrusted,
    string Hash);

public sealed record KnowledgeDocument(string Nombre, string Contenido);

/// <summary>Catalogo inmutable de chunks indexados al arrancar.</summary>
public interface IChunkCatalog
{
    IReadOnlyList<Chunk> Chunks { get; }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;

namespace TutorFlow.Application.Retrieval;

/// <summary>Segmentacion estructural determinista (SPEC 7.2).</summary>
public static partial class ChunkSegmenter
{
    [GeneratedRegex(@"^\*\*Artículo\s+(\d+)\.\s*(.*?)\.?\*\*", RegexOptions.CultureInvariant)]
    private static partial Regex ArticleRegex();

    [GeneratedRegex(@"^(#{2,3})\s+(.+?)\s*$", RegexOptions.CultureInvariant)]
    private static partial Regex HeadingRegex();

    [GeneratedRegex(@"^(\d+(?:\.\d+)*)\.?\s+(.+)$", RegexOptions.CultureInvariant)]
    private static partial Regex NumberedRegex();

    [GeneratedRegex(@"^Anexo\b\.?\s*(.*)$", RegexOptions.CultureInvariant | RegexOptions.IgnoreCase)]
    private static partial Regex AnexoRegex();

    private sealed record Draft(string Seccion, string Titulo, List<string> Lineas);

    public static IReadOnlyList<Chunk> Segment(string documento, string contenido)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(documento);
        ArgumentNullException.ThrowIfNull(contenido);

        var lineas = contenido.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
        var modoArticulos = lineas.Any(l => ArticleRegex().IsMatch(l));
        var vigente = !documento.Contains("2023", StringComparison.Ordinal);

        var drafts = new List<Draft>();
        Draft? actual = null;
        foreach (var linea in lineas)
        {
            var art = ArticleRegex().Match(linea);
            if (art.Success)
            {
                actual = new Draft($"Artículo {art.Groups[1].Value}", art.Groups[2].Value.Trim(), [linea]);
                drafts.Add(actual);
                continue;
            }

            var head = HeadingRegex().Match(linea);
            if (head.Success)
            {
                if (modoArticulos)
                {
                    actual = null; // capitulos: cierran el articulo previo, no generan chunk
                    continue;
                }

                var (seccion, titulo) = CanonicalizeHeading(head.Groups[2].Value);
                actual = new Draft(seccion, titulo, [linea]);
                drafts.Add(actual);
                continue;
            }

            actual?.Lineas.Add(linea);
        }

        var chunks = new List<Chunk>();
        foreach (var d in drafts)
        {
            var texto = string.Join("\n", d.Lineas).Trim();
            if (!modoArticulos && !TieneTextoPropio(d.Lineas))
            {
                continue; // seccion padre sin texto propio
            }

            chunks.Add(new Chunk(
                ChunkId: $"{documento}#{d.Seccion}",
                Documento: documento,
                Seccion: d.Seccion,
                Titulo: d.Titulo,
                Texto: texto,
                Vigente: vigente,
                Untrusted: false,
                Hash: Hash(texto)));
        }

        return chunks;
    }

    private static bool TieneTextoPropio(List<string> lineas) =>
        lineas.Skip(1).Any(l => !string.IsNullOrWhiteSpace(l));

    private static (string Seccion, string Titulo) CanonicalizeHeading(string heading)
    {
        var anexo = AnexoRegex().Match(heading);
        if (anexo.Success)
        {
            return ("Anexo", anexo.Groups[1].Value.Trim());
        }

        var num = NumberedRegex().Match(heading);
        if (num.Success)
        {
            return ($"Sección {num.Groups[1].Value}", num.Groups[2].Value.Trim());
        }

        return (heading.Trim(), heading.Trim());
    }

    internal static string Hash(string texto) =>
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(texto))).ToLowerInvariant();
}

public static class KnowledgeIndexer
{
    /// <summary>Segmenta todos los documentos (orden ordinal por nombre) y marca la cuarentena por lista de chunkId.</summary>
    public static IReadOnlyList<Chunk> Build(IEnumerable<KnowledgeDocument> documentos, IEnumerable<string> cuarentena)
    {
        ArgumentNullException.ThrowIfNull(documentos);
        ArgumentNullException.ThrowIfNull(cuarentena);
        var q = new HashSet<string>(cuarentena.Select(x => x.Trim()).Where(x => x.Length > 0), StringComparer.Ordinal);
        return documentos
            .OrderBy(d => d.Nombre, StringComparer.Ordinal)
            .SelectMany(d => ChunkSegmenter.Segment(d.Nombre, d.Contenido))
            .Select(c => q.Contains(c.ChunkId) ? c with { Untrusted = true } : c)
            .ToList();
    }
}

using System.Globalization;
using System.Text;

namespace TutorFlow.Application.Retrieval;

/// <summary>Normalizacion para BM25: minusculas, sin tildes, stopwords y stemming ligero.</summary>
public static class SpanishTextNormalizer
{
    private static readonly HashSet<string> Stopwords = new(StringComparer.Ordinal)
    {
        "a", "al", "algo", "ante", "como", "con", "contra", "cual", "cuales", "cuando", "cuanto", "cuantos", "cuantas",
        "de", "del", "desde", "donde", "e", "el", "ella", "ellos", "en", "entre", "era", "es", "esa", "ese", "eso",
        "esta", "estan", "este", "esto", "fue", "ha", "han", "hay", "la", "las", "le", "les", "lo", "los", "mas",
        "me", "mi", "mis", "muy", "ni", "no", "nos", "o", "para", "pero", "por", "porque", "que", "quien", "se",
        "sea", "ser", "si", "sin", "sobre", "son", "su", "sus", "tu", "tus", "un", "una", "uno", "unos", "unas",
        "y", "ya", "yo", "puedo", "puede", "tengo", "tiene",
    };

    public static string RemoveDiacritics(string text)
    {
        var d = text.Normalize(NormalizationForm.FormD);
        var sb = new StringBuilder(d.Length);
        foreach (var ch in d)
        {
            if (CharUnicodeInfo.GetUnicodeCategory(ch) != UnicodeCategory.NonSpacingMark)
            {
                sb.Append(ch);
            }
        }

        return sb.ToString().Normalize(NormalizationForm.FormC);
    }

    public static IReadOnlyList<string> Tokenize(string text)
    {
        if (string.IsNullOrEmpty(text))
        {
            return [];
        }

        var plain = RemoveDiacritics(text).ToLowerInvariant();
        var tokens = new List<string>();
        var sb = new StringBuilder();
        foreach (var ch in plain)
        {
            if (char.IsLetterOrDigit(ch))
            {
                sb.Append(ch);
            }
            else if (sb.Length > 0)
            {
                Flush(sb, tokens);
            }
        }

        if (sb.Length > 0)
        {
            Flush(sb, tokens);
        }

        return tokens;
    }

    private static void Flush(StringBuilder sb, List<string> tokens)
    {
        var word = sb.ToString();
        sb.Clear();
        if (Stopwords.Contains(word))
        {
            return;
        }

        tokens.Add(Stem(word));
    }

    /// <summary>Stemming ligero: plurales, "-ciones" y vocal final.</summary>
    internal static string Stem(string w)
    {
        if (w.Length == 0 || char.IsDigit(w[0]))
        {
            return w;
        }

        if (w.EndsWith("ciones", StringComparison.Ordinal))
        {
            w = w[..^6] + "cion";
        }
        else if (w.Length > 5 && w.EndsWith("es", StringComparison.Ordinal))
        {
            w = w[..^2];
        }
        else if (w.Length > 3 && w.EndsWith('s'))
        {
            w = w[..^1];
        }

        if (w.Length > 4 && (w.EndsWith('a') || w.EndsWith('e') || w.EndsWith('o')))
        {
            w = w[..^1];
        }

        return w;
    }
}

using System.Text.RegularExpressions;

namespace TutorFlow.Application.Retrieval;

/// <summary>
/// Detector heuristico de instrucciones incrustadas. SOLO para pruebas (SPEC 6.4, RAG-14.c):
/// no se usa para filtrar en ejecucion; la cuarentena es por lista.
/// </summary>
public static partial class InstructionDetector
{
    [GeneratedRegex(@"\b(ignora|ignore|olvida|omite)\w*\s+(todas?\s+)?(tus|las|sus|all|previous|prior)\b.{0,30}\b(instruccion\w*|instructions)", RegexOptions.CultureInvariant)]
    private static partial Regex IgnorePattern();

    [GeneratedRegex(@"\binstrucciones\s+anteriores\b|\b(previous|prior)\s+instructions\b|\bsystem\s+prompt\b", RegexOptions.CultureInvariant)]
    private static partial Regex PreviousPattern();

    [GeneratedRegex(@"\b(recordatorio|mensaje|nota)\s+(interno|interna)\s+para\s+(el|la)\s+(asistente|modelo|ia)\b", RegexOptions.CultureInvariant)]
    private static partial Regex AddressedToAssistantPattern();

    public static bool Detecta(string texto)
    {
        if (string.IsNullOrWhiteSpace(texto))
        {
            return false;
        }

        var t = SpanishTextNormalizer.RemoveDiacritics(texto).ToLowerInvariant();
        return IgnorePattern().IsMatch(t) || PreviousPattern().IsMatch(t) || AddressedToAssistantPattern().IsMatch(t);
    }
}

